var n=`1237-habichuelas-con-dulce`;var a=`world-1237`;var t=`DO`;var r=`central-america-caribbean`;var o=4;var s=649;var d={en:`Habichuelas con Dulce`,ua:`Солодка квасоля по-домініканськи`};var l={en:`Habichuelas con Dulce is a dish from Dominican Republic featuring kidney beans, coconut milk, evaporated milk, sweetened condensed milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Солодка квасоля по-домініканськи, страва кухні країни Домініканська Республіка з такими основними складниками: червона квасоля кідні, кокосове молоко, концентроване молоко без цукру, згущене молоко з цукром. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var c=[{en:`Soak the dried beans in ample clean cold water for about 450 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 450 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:450,i:[[`kidney-beans`,350,`g`],[`water`,900,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 95 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 95 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:95,i:[[`water`,1100,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 22 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 22 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:22,i:[[`coconut-milk`,500,`ml`],[`evaporated-milk`,300,`ml`],[`sweetened-condensed-milk`,200,`g`],[`cassia-cinnamon`,2,`pcs`],[`ground-cloves`,2,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 17 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 17 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:17,i:[[`sweet-potato`,280,`g`],[`raisin`,100,`g`]]},{en:`Refrigerate the prepared mixture for about 65 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 65 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:65,i:[]}];var u={slug:n,id:a,country:`DO`,region:r,servings:4,minutes:649,title:d,text:l,steps:c};export{t as country,u as default,a as id,s as minutes,r as region,o as servings,n as slug,c as steps,l as text,d as title};